public class BubbleSort {

    public static void main(String[] args) {

        int[] arr = {45, 12, 78, 23, 6};

        int n = arr.length;

        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - 1 - i; j++) {

                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }

        System.out.print("Sorted: ");
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

/*  Output:
    Sorted: 6 12 23 45 78                          */

public class BinarySearch {

    public static void main(String[] args) {

        // Binary Search-এর জন্য array অবশ্যই sorted
        int[] arr = {6, 12, 23, 45, 78, 91};
        int target = 45;

        int low = 0;
        int high = arr.length - 1;
        int position = -1;          // না পেলে -1

        while (low <= high) {

            int mid = (low + high) / 2;

            if (arr[mid] == target) {
                position = mid;
                break;
            } else if (arr[mid] < target) {
                low = mid + 1;      // ডান অর্ধেকে খোঁজো
            } else {
                high = mid - 1;     // বাম অর্ধেকে খোঁজো
            }
        }

        System.out.println("Index: " + position);
    }
}

